import sqlite3
import hashlib
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(b'admin_secret_2024').hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, api_key) VALUES (?, ?, ?, ?)",
               ('admin', admin_hash, 'admin', os.urandom(16).hex()))
    db.commit()
    db.close()

@app.route('/api/user/lookup', methods=['GET'])
def user_lookup():
    """Look up user details by username. Requires valid session."""
    username = request.args.get('username', '')
    api_key = request.headers.get('X-API-Key', '')

    # Verify API key exists in database
    db = get_db()
    caller = db.execute("SELECT * FROM users WHERE api_key = ?", (api_key,)).fetchone()
    if not caller:
        return jsonify({'error': 'unauthorized'}), 401

    # Log the lookup attempt
    db.execute("INSERT INTO audit_log (action, details) VALUES (?, ?)",
               ('lookup', f'caller={caller["username"]}, target={username}'))
    db.commit()

    # VULNERABLE: username is interpolated directly into SQL query
    # The developer used parameterized query above but forgot here
    query = f"SELECT id, username, role FROM users WHERE username = '{username}'"
    try:
        result = db.execute(query).fetchone()
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

    if result:
        return jsonify({'id': result[0], 'username': result[1], 'role': result[2]})
    return jsonify({'error': 'not found'}), 404

@app.route('/api/user/search', methods=['POST'])
def user_search():
    """Search users by partial match. Admin only."""
    api_key = request.headers.get('X-API-Key', '')
    db = get_db()
    caller = db.execute("SELECT * FROM users WHERE api_key = ?", (api_key,)).fetchone()
    if not caller or caller['role'] != 'admin':
        return jsonify({'error': 'forbidden'}), 403

    data = request.get_json(force=True)
    pattern = data.get('pattern', '')
    # This one uses parameterized query correctly
    results = db.execute("SELECT id, username, role FROM users WHERE username LIKE ?",
                         (f'%{pattern}%',)).fetchall()
    return jsonify([{'id': r[0], 'username': r[1], 'role': r[2]} for r in results])

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.1.3'})

@app.route('/api/debug/env', methods=['GET'])
def debug_env():
    """Debug endpoint - should be disabled in production"""
    if os.environ.get('FLASK_ENV') == 'development':
        return jsonify(dict(os.environ))
    return jsonify({'error': 'disabled'}), 403

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
